#include <stdio.h>
int main() {
    int a[10], i, j, temp;
    // 输入10个整数
    for (i = 0; i < 10; i++) {
        scanf("%d", &a[i]);
    }
    // 冒泡排序
    for (i = 0; i < 9; i++) {         // 外层控制轮数
        for (j = 0; j < 9 - i; j++) { // 内层控制比较
            if (a[j] > a[j+1]) {      // 相邻比较
                temp = a[j];          // 交换
                a[j] = a[j+1];
                a[j+1] = temp;
            }
        }
    }
    // 输出结果
    for (i = 0; i < 10; i++) {
        printf("%d ", a[i]);
    }
    return 0;
}

#include <stdio.h>
// 交换函数（地址传递）
void swap(int *a, int *b) {
    int temp;
    temp = *a;
    *a = *b;
    *b = temp;
}
int main() {
    int x = 3, y = 5;
    printf("交换前：x=%d, y=%d\n", x, y);
    swap(&x, &y);  // 传地址
    printf("交换后：x=%d, y=%d\n", x, y);
    return 0;
}

